package com.pipeline.engine;

import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.regex.*;

/**
 * BuildTemplateProcessor handles CI/CD pipeline template rendering
 * with feature flag support for gradual rollout of new build steps.
 */
public class BuildTemplateProcessor {

    private final FeatureFlagService featureFlags;
    private final Path templateRoot;
    private final Map<String, String> buildContext;
    private static final Pattern DIRECTIVE_PATTERN = Pattern.compile("<!--#(\\w+)\\s+(.*?)-->");
    private static final Pattern SAFE_VAR_PATTERN = Pattern.compile("^[A-Z_][A-Z0-9_]*$");

    public BuildTemplateProcessor(FeatureFlagService featureFlags, Path templateRoot) {
        this.featureFlags = featureFlags;
        this.templateRoot = templateRoot;
        this.buildContext = new ConcurrentHashMap<>();
    }

    public void setBuildVariable(String key, String value) {
        if (!SAFE_VAR_PATTERN.matcher(key).matches()) {
            throw new IllegalArgumentException("Invalid variable name: " + key);
        }
        buildContext.put(key, value);
    }

    /**
     * Processes a pipeline configuration template, resolving directives.
     * Feature flag 'enhanced_template_engine' controls whether advanced
     * directives (include, exec) are processed.
     */
    public String processTemplate(String templateName, Map<String, String> userParams) throws IOException {
        Path templatePath = templateRoot.resolve(templateName).normalize();
        if (!templatePath.startsWith(templateRoot)) {
            throw new SecurityException("Path traversal detected");
        }
        String content = new String(Files.readAllBytes(templatePath));
        return resolveDirectives(content, userParams, 0);
    }

    private String resolveDirectives(String content, Map<String, String> userParams, int depth) throws IOException {
        if (depth > 5) {
            throw new SecurityException("Maximum template nesting depth exceeded");
        }

        StringBuilder result = new StringBuilder();
        Matcher matcher = DIRECTIVE_PATTERN.matcher(content);
        int lastEnd = 0;

        while (matcher.find()) {
            result.append(content, lastEnd, matcher.start());
            String directive = matcher.group(1);
            String args = matcher.group(2).trim();
            result.append(handleDirective(directive, args, userParams, depth));
            lastEnd = matcher.end();
        }
        result.append(content, lastEnd, content.length());
        return result.toString();
    }

    private String handleDirective(String directive, String args, Map<String, String> userParams, int depth) throws IOException {
        switch (directive) {
            case "echo":
                return handleEcho(args, userParams);
            case "set":
                return handleSet(args, userParams);
            case "include":
                return handleInclude(args, userParams, depth);
            case "exec":
                return handleExec(args, userParams);
            case "if":
                return handleConditional(args, userParams);
            default:
                return "<!-- unknown directive: " + sanitizeOutput(directive) + " -->";
        }
    }

    private String handleEcho(String args, Map<String, String> userParams) {
        String varName = extractAttribute(args, "var");
        if (varName == null) return "";
        String value = buildContext.getOrDefault(varName, userParams.getOrDefault(varName, ""));
        return sanitizeOutput(value);
    }

    private String handleSet(String args, Map<String, String> userParams) {
        String varName = extractAttribute(args, "var");
        String value = extractAttribute(args, "value");
        if (varName != null && value != null && SAFE_VAR_PATTERN.matcher(varName).matches()) {
            buildContext.put(varName, value);
        }
        return "";
    }

    private String handleInclude(String args, Map<String, String> userParams, int depth) throws IOException {
        if (!featureFlags.isEnabled("enhanced_template_engine")) {
            return "<!-- include disabled -->";
        }
        String file = extractAttribute(args, "virtual");
        if (file == null) file = extractAttribute(args, "file");
        if (file == null) return "";

        // Resolve variables in the file path
        file = interpolateVariables(file, userParams);

        Path includePath = templateRoot.resolve(file).normalize();
        if (!includePath.startsWith(templateRoot)) {
            throw new SecurityException("Path traversal in include");
        }
        String included = new String(Files.readAllBytes(includePath));
        return resolveDirectives(included, userParams, depth + 1);
    }

    private String handleExec(String args, Map<String, String> userParams) throws IOException {
        if (!featureFlags.isEnabled("enhanced_template_engine")) {
            return "<!-- exec disabled -->";
        }
        // Only allow exec when pipeline is in 'trusted' mode
        if (!"true".equals(buildContext.get("TRUSTED_MODE"))) {
            return "<!-- exec requires trusted mode -->";
        }
        String cmd = extractAttribute(args, "cmd");
        if (cmd == null) return "";

        // Validate command against allowlist
        if (!isAllowedCommand(cmd)) {
            return "<!-- command not in allowlist -->";
        }

        Process process = Runtime.getRuntime().exec(new String[]{"/bin/sh", "-c", cmd});
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
            StringBuilder output = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }
            return sanitizeOutput(output.toString());
        }
    }

    private String handleConditional(String args, Map<String, String> userParams) {
        String expr = extractAttribute(args, "expr");
        if (expr == null) return "";
        // Simple equality check: ${VAR}=="value"
        Pattern eqPattern = Pattern.compile("\\$\\{(\\w+)\\}==\"(.*?)\"");
        Matcher m = eqPattern.matcher(expr);
        if (m.matches()) {
            String varName = m.group(1);
            String expected = m.group(2);
            String actual = buildContext.getOrDefault(varName, userParams.getOrDefault(varName, ""));
            return String.valueOf(actual.equals(expected));
        }
        return "false";
    }

    private boolean isAllowedCommand(String cmd) {
        List<String> allowlist = Arrays.asList("date", "whoami", "hostname", "uname -a", "cat /etc/os-release");
        String normalizedCmd = cmd.trim().toLowerCase();
        return allowlist.stream().anyMatch(allowed -> normalizedCmd.startsWith(allowed));
    }

    /**
     * Interpolates ${VAR_NAME} references in a string using build context and user params.
     * This enables dynamic path resolution in templates.
     */
    private String interpolateVariables(String input, Map<String, String> userParams) {
        Pattern varPattern = Pattern.compile("\\$\\{(\\w+)\\}");
        Matcher m = varPattern.matcher(input);
        StringBuffer sb = new StringBuffer();
        while (m.find()) {
            String varName = m.group(1);
            String replacement = buildContext.getOrDefault(varName, userParams.getOrDefault(varName, ""));
            m.appendReplacement(sb, Matcher.quoteReplacement(replacement));
        }
        m.appendTail(sb);
        return sb.toString();
    }

    private String extractAttribute(String args, String attrName) {
        Pattern attrPattern = Pattern.compile(attrName + "=\"(.*?)\"");
        Matcher m = attrPattern.matcher(args);
        if (m.find()) {
            return m.group(1);
        }
        return null;
    }

    private String sanitizeOutput(String input) {
        if (input == null) return "";
        return input.replace("<", "&lt;").replace(">", "&gt;").replace("&", "&amp;");
    }
}

class FeatureFlagService {
    private final Map<String, Boolean> flags = new ConcurrentHashMap<>();

    public FeatureFlagService() {
        // Default flags - enhanced_template_engine is rolled out to 50% of pipelines
        flags.put("enhanced_template_engine", true);
        flags.put("parallel_builds", true);
        flags.put("artifact_caching", false);
    }

    public boolean isEnabled(String flagName) {
        return flags.getOrDefault(flagName, false);
    }

    public void setFlag(String flagName, boolean value) {
        flags.put(flagName, value);
    }
}
